    for position, (envelope, raw) in enumerate(
        zip(envelopes, validated_receipt_bytes)
    ):
        if envelope is None:
            invalid_digests[position] = hashlib.sha256(raw).hexdigest()
            tally_input.append({
                TICKET_PAYLOAD: {
                    FE_EXECUTION_MOMENT: 0,
                    FE_SITE_VERSION: "",
                    KEY_VERSION: 0,
                    FE_OPERATION_ID: "",
                    FE_PLAN_DIGEST: "00" * 32,
                    FE_PREVIOUS: "00" * 32,
                    FE_RESULT: FE_RESULT_FAILED,
                    FE_SITE: "",
                    FE_POST_DIGEST: None,
                },
                SIGNATURE: "00" * 32,
                "_invalid_digest": invalid_digests[position],
            })
